 public static class Program {
  [STAThread]public static int Main(string[] args){Directory.CreateDirectory(Path.Combine(Store.Root,"work"));Environment.SetEnvironmentVariable("TEMP",Path.Combine(Store.Root,"work"));Environment.SetEnvironmentVariable("TMP",Path.Combine(Store.Root,"work"));bool testing=args.Length>0&&(args[0]=="--test"||args[0]=="--soak"||args[0]=="--endurance");Mutex mutex=null;
   try{if(!testing){bool created;mutex=new Mutex(true,"Local\\GujiDesktopPet",out created);if(!created){MessageBox.Show("咕叽已经在陪着你啦。可以从任务栏右下角的托盘图标打开或找回它。","咕叽");return 0;}}
    var app=new Application{ShutdownMode=testing?ShutdownMode.OnExplicitShutdown:ShutdownMode.OnLastWindowClose};
    app.DispatcherUnhandledException+=(s,e)=>{try{Directory.CreateDirectory(Path.Combine(Store.Root,"work"));File.AppendAllText(Path.Combine(Store.Root,"work","error.log"),DateTime.Now+" "+e.Exception+Environment.NewLine);}catch{}if(!testing)MessageBox.Show("咕叽遇到了一点问题，详情保存在程序旁的 work/error.log。\n"+e.Exception.Message,"咕叽");};
    if(testing){if(args[0]=="--soak")return Tests.Soak(app);if(args[0]=="--endurance")return Tests.Endurance(app);int result=Tests.Run();app.Shutdown();return result;}
    var settings=Store.Load();var pet=new PetWindow(settings,false);app.MainWindow=pet;app.Run(pet);return 0;
   }catch(Exception ex){try{Directory.CreateDirectory(Path.Combine(Store.Root,"work"));File.WriteAllText(Path.Combine(Store.Root,"work","startup-error.txt"),ex.ToString());}catch{}if(!testing)MessageBox.Show("启动失败："+ex.Message+"\n请将程序和 assets 文件夹一起解压，再重新打开。","咕叽");return 1;}finally{if(mutex!=null)mutex.Dispose();}
  }
