 public static class Tests {
  static List<string> log=new List<string>();static int failures;
  static void Check(bool yes,string name){log.Add((yes?"PASS ":"FAIL ")+name);if(!yes)failures++;}
  static void Pump(){var f=new DispatcherFrame();Dispatcher.CurrentDispatcher.BeginInvoke(DispatcherPriority.Background,new Action(()=>f.Continue=false));Dispatcher.PushFrame(f);}
  static void AwaitAnimation(int ms){var frame=new DispatcherFrame();var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(ms)};timer.Tick+=(s,e)=>{timer.Stop();frame.Continue=false;};timer.Start();Dispatcher.PushFrame(frame);}
  static void Snapshot(Window w,string file){w.UpdateLayout();Pump();int x=(int)w.ActualWidth,y=(int)w.ActualHeight;var b=new RenderTargetBitmap(x,y,96,96,PixelFormats.Pbgra32);b.Render(w);var p=new PngBitmapEncoder();p.Frames.Add(BitmapFrame.Create(b));using(var f=File.Create(file))p.Save(f);}
    static IEnumerable<System.Windows.Controls.Button> Buttons(DependencyObject root){if(root==null)yield break;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++){var child=VisualTreeHelper.GetChild(root,i);var button=child as System.Windows.Controls.Button;if(button!=null)yield return button;foreach(var b in Buttons(child))yield return b;}}
  static T Find<T>(DependencyObject root) where T:DependencyObject {if(root is T)return (T)root;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++){var found=Find<T>(VisualTreeHelper.GetChild(root,i));if(found!=null)return found;}return null;}
  static void Click(Window w,string name,bool tooltip=false){foreach(var b in Buttons(w)){if((tooltip?Convert.ToString(b.ToolTip):Convert.ToString(b.Content))==name){b.RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Button.ClickEvent));Pump();return;}}throw new Exception("Button not found: "+name);}
  public static int Soak(Application app){var p=new PetWindow(new Settings{Onboarded=true},true);p.Show();p.StartRuntimeForTest();var sw=System.Diagnostics.Stopwatch.StartNew();var process=System.Diagnostics.Process.GetCurrentProcess();var before=process.TotalProcessorTime;var t=new DispatcherTimer{Interval=TimeSpan.FromSeconds(1)};int n=0;t.Tick+=(s,e)=>{n++;if(n==4){p.View.Save(Path.Combine(Store.Root,"work","runtime.png"),720,800);p.Drink();}if(n==9){p.Bed();p.ToggleLamp();}if(n>=15){t.Stop();process.Refresh();File.WriteAllText(Path.Combine(Store.Root,"work","runtime-report.txt"),"ElapsedSeconds="+sw.Elapsed.TotalSeconds+"\r\nCpuSeconds="+(process.TotalProcessorTime-before).TotalSeconds+"\r\nWorkingSetMB="+(process.WorkingSet64/1048576.0)+"\r\nSleeping="+p.View.Sleeping);p.Close();app.Shutdown();}};t.Start();app.Run();return 0;}
  public static int Endurance(Application app){
   var p=new PetWindow(new Settings{Onboarded=true},true);p.Show();p.StartRuntimeForTest();var timer=new DispatcherTimer{Interval=TimeSpan.FromSeconds(2)};var sw=System.Diagnostics.Stopwatch.StartNew();var process=System.Diagnostics.Process.GetCurrentProcess();TimeSpan before=process.TotalProcessorTime;int phase=0,lastFrames=0;string report=Path.Combine(Store.Root,"work","endurance-report.txt");File.WriteAllText(report,"Start="+DateTime.Now.ToString("O")+Environment.NewLine);int ticks=0;
   timer.Tick+=(sender,e)=>{ticks++;double time=sw.Elapsed.TotalSeconds;if(ticks%5==0){process.Refresh();File.AppendAllText(report,"Seconds="+time.ToString("F1")+" CPU="+(process.TotalProcessorTime-before).TotalSeconds.ToString("F3")+" WorkingSetMB="+(process.WorkingSet64/1048576.0).ToString("F1")+" Frames="+p.FrameCount+" Sleeping="+p.View.Sleeping+Environment.NewLine);}
    if(phase==0&&time>=20){phase=1;lastFrames=p.FrameCount;p.OfferFood(6);}
    if(phase==1&&time>=24){phase=2;p.Eat(6);}
    if(phase==2&&time>=30){phase=3;p.Drink();}
    if(phase==3&&time>=40){phase=4;p.Bed();}
    if(phase==4&&time>=45){phase=5;p.ToggleLamp();}
    if(phase==5&&time>=65){phase=6;p.Wake(false);p.Apply(Array.Find(Wardrobe.Sets,o=>o.Name=="星夜冬眠"));p.Pounce();}
    if(phase==6&&time>=72){phase=7;p.Panels.WardrobePanel();}
    if(phase==7&&time>=80){phase=8;if(p.Panels.Current!=null)p.Panels.Current.Close();p.ShowReminder("water");}
    if(phase==8&&time>=86){phase=9;p.CloseReminder();p.Config.Focus=true;p.Quieten();}
    if(time>=95){timer.Stop();bool ok=p.FrameCount>lastFrames&&p.View.Drag.Phase==DragPhase.Rest&&p.ReminderWindow==null&&p.Config.Focus;File.AppendAllText(report,"Result="+(ok?"PASS":"FAIL")+Environment.NewLine);p.Close();app.Shutdown(ok?0:2);}
   };timer.Start();app.Run();return 0;
  }
