   var fitted=new DrawingVisual();using(var dc=fitted.RenderOpen()){dc.DrawRectangle(Art.Brush("#F2F6ED"),null,new Rect(0,0,900,900));for(int i=0;i<9;i++){var outfit=i==0?Array.Find(Wardrobe.Sets,o=>o.Name=="星夜冬眠"):Wardrobe.Sets[12+i];var visual=new PetVisual(new Settings{Wear=outfit.Copy()}){Preview=true};visual.Measure(new Size(360,400));visual.Arrange(new Rect(0,0,360,400));var bitmap=new RenderTargetBitmap(360,400,96,96,PixelFormats.Pbgra32);bitmap.Render(visual);double x=i%3*300,y=i/3*300;dc.DrawImage(bitmap,new Rect(x,y-30,300,333));Art.Text(dc,(i==0?"参考 · ":"")+outfit.Name,16,Art.Brush("#35543E"),new Point(x+88,y+275));}}SaveVisual(fitted,Path.Combine(work,"outfits-single-layer.png"),900,900);
   var pet=new PetVisual(new Settings()){Preview=true};pet.Measure(new Size(360,400));pet.Arrange(new Rect(0,0,360,400));var b=new RenderTargetBitmap(360,400,96,96,PixelFormats.Pbgra32);b.Render(pet);var board=new DrawingVisual();using(var dc=board.RenderOpen()){for(int i=0;i<2;i++){double x=i*420;dc.DrawRectangle(Art.Brush(i==0?"#E8EDDF":"#162C36"),null,new Rect(x,0,420,450));for(int j=0;j<5;j++)dc.DrawLine(new Pen(Art.Brush(i==0?"#BDCEB1":"#39636E"),16),new Point(x,100+j*50),new Point(x+420,25+j*50));dc.DrawImage(b,new Rect(x+30,10,360,400));Art.Text(dc,i==0?"实际绘制 · 浅色背景":"实际绘制 · 深色背景",16,i==0?Art.Brush("#35543E"):Brushes.WhiteSmoke,new Point(x+100,416));}}SaveVisual(board,Path.Combine(work,"contrast.png"),840,450);
  }
